/** The bridge the runtime speaks through: generic protocol in, typed store out. */
class ModerationStoreResolver(
    private val store: ModerationStore,
    model: Model,
) : StateResolver {
    private val questions = ModerationStoreQuestions(model)

    override fun begin(kind: WorkKind): UnitOfWork = store.begin(kind)

    override fun fetchByKeys(shape: String, keys: List<StoreKey>): List<Row> = when (shape) {
        "Seller" -> store.sellers(keys).map { it.toRow() }
        "Listing" -> store.listings(keys).map { it.toRow() }
        "PublicationNotice" -> store.publicationNotices(keys).map { it.toRow() }
        "SellerNotice" -> store.sellerNotices(keys).map { it.toRow() }
        "DraftClosure" -> store.draftClosures(keys).map { it.toRow() }
        "ListingReport" -> store.listingReports(keys).map { it.toRow() }
        "ReporterNotice" -> store.reporterNotices(keys).map { it.toRow() }
        "DiscardRecord" -> store.discardRecords(keys).map { it.toRow() }
        "DiscardRefusal" -> store.discardRefusals(keys).map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchAll(shape: String): List<Row> = when (shape) {
        "Seller" -> store.allSellers().map { it.toRow() }
        "Listing" -> store.allListings().map { it.toRow() }
        "PublicationNotice" -> store.allPublicationNotices().map { it.toRow() }
        "SellerNotice" -> store.allSellerNotices().map { it.toRow() }
        "DraftClosure" -> store.allDraftClosures().map { it.toRow() }
        "ListingReport" -> store.allListingReports().map { it.toRow() }
        "ReporterNotice" -> store.allReporterNotices().map { it.toRow() }
        "DiscardRecord" -> store.allDiscardRecords().map { it.toRow() }
        "DiscardRefusal" -> store.allDiscardRefusals().map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchReferencingAny(shape: String, field: String, targets: List<Ref.Persisted>): List<Row> = when {
        shape == "Listing" && field == "seller" -> store.listingsBySellers(targets).map { it.toRow() }
        shape == "SellerNotice" && field == "seller" -> store.sellerNoticesBySellers(targets).map { it.toRow() }
        shape == "ListingReport" && field == "listing" -> store.listingReportsByListings(targets).map { it.toRow() }
        shape == "ReporterNotice" && field == "report" -> store.reporterNoticesByReports(targets).map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchCandidates(shape: String, filter: QF): List<Row> {
        if (shape == "Listing")
            questions.draftCandidates.match(filter)?.let { h -> return store.draftCandidates().map { it.toRow() } }
        if (shape == "Listing")
            questions.publishedListingCandidates.match(filter)?.let { h -> return store.publishedListingCandidates().map { it.toRow() } }
        if (shape == "ListingReport")
            questions.notifyReporterCandidates.match(filter)?.let { h -> return store.notifyReporterCandidates().map { it.toRow() } }
        if (shape == "Listing")
            questions.never1Candidates.match(filter)?.let { h -> return store.never1Candidates().map { it.toRow() } }
        return fetchAll(shape) // unrecognized filters fall back to the scan floor
    }

    override fun fetchCaptures(instance: Ref.Persisted, refinement: String): Map<String, Any?>? = when (refinement) {
        else -> null
    }
}

